from __future__ import annotations

import json
import os
import shutil
from pathlib import Path

if __package__:
    from .material_profiles import resolve_task_material_profile
else:
    from material_profiles import resolve_task_material_profile


APP_ROOT = Path(__file__).resolve().parent
TASKS_ROOT = APP_ROOT / "tasks"
DEFAULT_WORKSPACE_ROOT = Path(os.environ.get("SCI_BENCH_WORKSPACE_ROOT", "/workspace"))


def normalize_task_id(task_id: str) -> str:
    stripped = task_id.strip()
    if stripped.startswith("task_"):
        return stripped
    if not stripped.isdigit():
        raise ValueError("task_id must be numeric, e.g. 001, or task_NNN")
    return f"task_{int(stripped):03d}"


def load_task_metadata(task_dir: Path) -> dict[str, object]:
    metadata_path = task_dir / "metadata.json"
    with metadata_path.open("r", encoding="utf-8") as handle:
        metadata = json.load(handle)

    if not isinstance(metadata, dict):
        raise ValueError(f"Task metadata must be a JSON object: {metadata_path}")
    return metadata


def resolve_public_task(task_id: str) -> tuple[str, Path]:
    normalized = normalize_task_id(task_id)
    task_dir = TASKS_ROOT / normalized

    if not task_dir.is_dir():
        raise FileNotFoundError(f"Task directory not found: {task_dir}")

    return normalized, task_dir


def clear_directory(path: Path) -> None:
    for child in path.iterdir():
        if child.is_dir():
            shutil.rmtree(child)
        else:
            child.unlink()


def copy_agent_visible_files(
    task_dir: Path,
    workspace_task_dir: Path,
    *,
    material_profile: str | None = None,
) -> None:
    profile = resolve_task_material_profile(task_dir, material_profile)
    visible_entries = profile.visible_entries

    ignore = shutil.ignore_patterns("__pycache__", ".pytest_cache")

    for entry in visible_entries:
        if not isinstance(entry, str):
            raise ValueError(
                f"Invalid agent-visible entry in {task_dir / 'metadata.json'}: {entry!r}"
            )

        source_path = task_dir / entry
        if not source_path.exists():
            raise FileNotFoundError(f"Agent-visible path not found: {source_path}")

        destination_path = workspace_task_dir / entry
        destination_path.parent.mkdir(parents=True, exist_ok=True)

        if source_path.is_dir():
            shutil.copytree(source_path, destination_path, ignore=ignore, dirs_exist_ok=True)
        else:
            shutil.copy2(source_path, destination_path)


def prepare_workspace(
    task_id: str,
    force: bool = False,
    *,
    material_profile: str | None = None,
) -> Path:
    normalized, task_dir = resolve_public_task(task_id)
    workspace_task_dir = DEFAULT_WORKSPACE_ROOT / normalized

    if workspace_task_dir.exists():
        if not force:
            return workspace_task_dir
        clear_directory(workspace_task_dir)

    DEFAULT_WORKSPACE_ROOT.mkdir(parents=True, exist_ok=True)
    workspace_task_dir.mkdir(parents=True, exist_ok=True)
    copy_agent_visible_files(
        task_dir,
        workspace_task_dir,
        material_profile=material_profile,
    )
    return workspace_task_dir
"""Task-local auxiliary-material profile resolution.

The sidecar declaration is intentionally not part of an agent-visible payload.
It is consumed while task images are staged, then the staged metadata is
rewritten to the resolved profile allowlist.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any


WITH_AUXILIARY = "with_auxiliary"
WITHOUT_AUXILIARY = "without_auxiliary"
DEFAULT_MATERIAL_PROFILE = WITH_AUXILIARY
MATERIAL_PROFILES = (WITH_AUXILIARY, WITHOUT_AUXILIARY)
DECLARATION_FILENAME = "auxiliary_materials.json"
SUPPORTED_AUXILIARY_KINDS = frozenset(
    {
        "scientific_reference",
        "reference_bundle",
        "method_note",
        "supplementary_context",
        "reference_implementation",
    }
)
CORE_PROFILE_TEXT_FILES = (
    "instruction.md",
    "problem_desc.txt",
    "reproduction.md",
)


@dataclass(frozen=True)
class AuxiliaryMaterial:
    path: str
    kind: str

    def as_dict(self) -> dict[str, str]:
        return {"path": self.path, "kind": self.kind}


@dataclass(frozen=True)
class TaskMaterialProfile:
    """Resolved task entries for one agent-visible material profile."""

    name: str
    full_entries: tuple[str, ...]
    visible_entries: tuple[str, ...]
    auxiliary_materials: tuple[AuxiliaryMaterial, ...]
    declaration_sha256: str | None

    @property
    def removed_materials(self) -> tuple[AuxiliaryMaterial, ...]:
        if self.name == WITHOUT_AUXILIARY:
            return self.auxiliary_materials
        return ()

    def digest(self) -> str:
        payload = {
            "schema_version": 1,
            "profile": self.name,
            "full_entries": list(self.full_entries),
            "visible_entries": list(self.visible_entries),
            "auxiliary_materials": [item.as_dict() for item in self.auxiliary_materials],
            "declaration_sha256": self.declaration_sha256,
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode(
            "utf-8"
        )
        return hashlib.sha256(encoded).hexdigest()

    def as_record(self) -> dict[str, object]:
        return {
            "name": self.name,
            "declaration_sha256": self.declaration_sha256,
            "profile_digest": self.digest(),
            "full_visible_entries": list(self.full_entries),
            "visible_entries": list(self.visible_entries),
            "auxiliary_materials": [item.as_dict() for item in self.auxiliary_materials],
            "removed_auxiliary_materials": [
                item.as_dict() for item in self.removed_materials
            ],
        }


def normalize_material_profile(value: str | None) -> str:
    profile = (value or DEFAULT_MATERIAL_PROFILE).strip()
    if profile not in MATERIAL_PROFILES:
        raise ValueError(
            f"Unsupported material profile: {profile!r}. "
            f"Expected one of: {', '.join(MATERIAL_PROFILES)}"
        )
    return profile


def declaration_path(task_dir: Path) -> Path:
    return task_dir / DECLARATION_FILENAME


def load_json_object(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON: {path}") from exc
    if not isinstance(payload, dict):
        raise ValueError(f"Expected a JSON object: {path}")
    return payload


def _validate_relative_path(value: object, *, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{label} must be a non-empty string")
    if "\\" in value:
        raise ValueError(f"{label} must use POSIX-style relative paths: {value!r}")
    path = Path(value)
    if value == "." or path.is_absolute() or ".." in path.parts:
        raise ValueError(f"Unsafe {label}: {value!r}")
    return value


def _metadata_entries(task_dir: Path) -> tuple[str, ...]:
    metadata_path = task_dir / "metadata.json"
    metadata = load_json_object(metadata_path)
    entries = metadata.get("agent_entry_files")
    if not isinstance(entries, list) or not entries:
        raise ValueError(f"Missing non-empty agent_entry_files: {metadata_path}")

    normalized: list[str] = []
